  "Aucune coche = toutes les cadences, y compris les inconnues.": "Ninguna selección = todos los controles de tiempo, incluidos los desconocidos.",
  "L’Elo provient du PGN et doit respecter la plage pour les deux joueurs. Sans Elo, une partie est exclue si une borne est définie. Une cadence non renseignée ou non reconnue dans le PGN est « Inconnue ». Ces parties sont exclues si des cadences sont cochées, sauf si « Inconnue » est choisie.": "Elo proviene del PGN y debe estar dentro del rango para ambos jugadores. los juegos de ajedrez sin Elo se excluyen cuando se establece un límite. Los controles de tiempo PGN faltantes o no reconocidos son \"No conocidos\". Estos juegos de ajedrez se excluyen cuando se seleccionan los controles de tiempo, a menos que se seleccione \"No conocido\".",
  ": indique un nombre valide pour la borne Elo.": ": introduzca un número válido para la línea Elo.",
  ": choisis un Elo entier entre 0 et 4000, ou laisse la borne vide.": ": introduzca un número entero Elo de 0 a 4000, o deje en blanco el punto vinculado.",
  ": le minimum Elo ne peut pas dépasser le maximum.": ": el mínimo Elo no puede exceder el máximo Elo.",
  "Crée une base et importe des parties PGN dans la bibliothèque.": "Crear una base de datos e importar PGN juegos de ajedrez en la biblioteca.",
  "Maîtres Lichess ne propose pas de filtre par Elo ou cadence. Pour filtrer une collection de maîtres, choisis une base importée comme Mega Database.": "Lichess maestros no tiene Elo o filtros de control del tiempo. Para filtrar una colección principal, elija una base de datos importada como Mega Database.",
  "Source principale": "Fuente principal",
  "Mes bases PGN": "Mis bases de datos PGN",
  "Seuls les coups joués de la ligne principale sont comptés. Les variantes d’analyse ne gonflent pas les statistiques.": "Sólo se cuentan los movimientos de ajedrez de la línea principal. Las variaciones de análisis no inflan las estadísticas.",
