  "Choisis ton camp directement dans l’explorateur. Seules les réponses adverses comptent ; tes coups sont supposés joués. Cette estimation suit la variante affichée et les filtres de la base sélectionnée. Pour un PGN démarrant sur un diagramme, elle est conditionnelle à ce départ.": "Elige tu lado directamente en el explorador. Sólo cuentan las respuestas del oponente, se asumen sus movimientos de ajedrez. Esta estimación sigue la variación mostrada y los filtros de base de datos seleccionados. Para un PGN que comience a partir de un diagrama, depende de esa posición de partida.",
  "Mode d’analyse": "Modo de análisis",
  "Rapide (~250 ms par coup)": "Rápido (~ 250 ms por movimiento de ajedrez)",
  "Une profondeur plus élevée affine l’analyse et demande plus de temps. De 8 à 30, avec une limite de 10 secondes par coup. Si la cible n’est pas atteinte, ≈ signale l’évaluation obtenue ; sa profondeur réelle est visible au survol.": "Una mayor profundidad mejora el análisis y lleva más tiempo. De 8 a 30, con un límite de 10 segundos por movimiento de ajedrez. Si no se alcanza el objetivo, ≈ marca el resultado; hover para ver su profundidad real.",
