  "Cette base sert de référence à l’explorer et à la recherche de positions. Pour travailler une partie ou la réviser, ouvre-la dans l’analyse et sauvegarde une copie dans une base personnelle.": "Esta base de datos es una referencia para el explorador y la búsqueda de posiciones. Para estudiar o revisar un juego de ajedrez, abrirlo en análisis y guardar una copia en una base de datos personal.",
