  "Stockfish est nécessaire pour noter les coups dans Guess the Move. Le répertoire et la lecture sont disponibles sans moteur.": "Stockfish es necesario para puntuar las jugadas en Guess the Move. El repertorio y la lectura funcionan sin motor.",
