  "Stockfish active l’analyse et Guess the Move. Maia est facultatif pour jouer contre un adversaire au style humain. Aucun téléchargement ne commence avant ton choix.": "Stockfish activa el análisis y Guess the Move. Maia es opcional para jugar contra un rival de estilo humano. Las descargas solo empiezan cuando tú lo decides.",
