  "Équilibré (recommandé)": "Equilibrado (recomendado)",
  "Les profils recommandés laissent de la capacité pour les autres applications. Choisis Personnalisé pour ajuster les valeurs.": "Los perfiles recomendados dejan capacidad para otras aplicaciones. Elige Personalizado para ajustar los valores.",
  "Budget CPU (cœurs logiques)": "Presupuesto de CPU (núcleos lógicos)",
  "Cache mémoire Stockfish total (Mo)": "Caché de memoria total de Stockfish (MB)",
  "Le cache mémoire est partagé entre les deux moteurs Stockfish. Ce réglage ne plafonne pas la RAM totale de ChessGym : Maia, les imports et l’interface utilisent aussi de la mémoire.": "La caché de memoria se comparte entre los dos motores Stockfish. Este ajuste no limita la RAM total de ChessGym: Maia, las importaciones y la interfaz también utilizan memoria.",
  "Le budget CPU est partagé entre les calculs et les imports. Les tâches attendent si le budget est déjà utilisé. Les changements s’appliquent aux prochaines tâches.": "El presupuesto de CPU se comparte entre los cálculos y las importaciones. Las tareas esperan si el presupuesto ya está en uso. Los cambios se aplican a las próximas tareas.",
  "La configuration enregistrée a été adaptée aux ressources de ce serveur.": "La configuración guardada se ha adaptado a los recursos de este servidor.",
  "Choix : {cores} cœurs logiques, {memory} Mo de cache et {workers} processus d’importation.": "Selección: {cores} núcleos lógicos, {memory} MB de caché y {workers} procesos de importación.",
  "Avec ce petit budget CPU, certaines analyses et importations se déroulent l’une après l’autre.": "Con este presupuesto de CPU reducido, algunos análisis e importaciones se realizan uno tras otro.",
  "Choisis un nombre de cœurs compris dans les limites de ce serveur.": "Elige un número de núcleos dentro de los límites de este servidor.",
