  "Choisis une profondeur entière positive, ou le mode rapide.": "Elige una profundidad entera positiva o el modo rápido.",
  "La profondeur doit être un entier positif compatible avec le moteur.": "La profundidad debe ser un número entero positivo compatible con el motor.",
  "Le temps par position doit être un entier d’au moins 100 ms, représentable sans perte.": "El tiempo por posición debe ser un número entero de al menos 100 ms que pueda representarse sin pérdida de precisión.",
  "Choisis une durée ou une profondeur pour analyser la partie.": "Elige una duración o una profundidad para analizar la partida.",
  "Choisis une profondeur positive. Le calcul continue jusqu’à cette cible, sans limite de temps ajoutée. Une profondeur élevée peut demander longtemps ; tu peux arrêter les évaluations ou changer de position.": "Elige una profundidad positiva. El cálculo continúa hasta ese objetivo, sin añadir un límite de tiempo. Una profundidad elevada puede requerir mucho tiempo; puedes detener las evaluaciones o cambiar de posición.",
  "Choisis une profondeur entière positive compatible avec le moteur.": "Elige una profundidad entera positiva compatible con el motor.",
  ", sans limite de temps ajoutée. ≈ indique une cible non atteinte.": ", sin añadir un límite de tiempo. ≈ indica un objetivo no alcanzado.",
  " non atteinte": " no alcanzada",
  "Durée par position": "Tiempo por posición",
  "En mode profondeur, chaque position est analysée jusqu’à la cible, sans limite de temps ajoutée. En mode durée, le calcul utilise le temps choisi. Tu peux continuer à utiliser ChessGym ou annuler le bilan.": "En el modo de profundidad, cada posición se analiza hasta el objetivo, sin añadir un límite de tiempo. En el modo de duración, el cálculo utiliza el tiempo elegido. Puedes seguir usando ChessGym o cancelar el informe.",
  "Choisis une durée d’au moins 0,1 seconde, avec au plus trois décimales.": "Elige una duración de al menos 0,1 segundos, con un máximo de tres decimales.",
  "Choisis une durée, une profondeur cible ou un calcul sans limite.": "Elige una duración, una profundidad objetivo o un cálculo sin límite.",
  "Le calcul vise cette profondeur sans limite de temps. La profondeur atteignable dépend du moteur.": "El cálculo busca alcanzar esta profundidad sin límite de tiempo. La profundidad alcanzable depende del motor.",
  "Désactive le moteur ou change de position pour arrêter le calcul.": "Desactiva el motor o cambia de posición para detener el cálculo."
